import { IProject, ITriggerActionGroup, ITriggerAction, ITriggerGroup, IActionGroup, ITrigger, IAction } from '@droid/project-v2-interface';

// 辅助类型，确保返回值类型正确
type Finder<T> = (project: IProject, ulid: string) => T | undefined;

export const entityFinders = {
  triggerActionGroup: ((project, ulid) => {
    return project.children?.find(g => g.ulid === ulid);
  }) as Finder<ITriggerActionGroup>,
  
  triggerAction: ((project, ulid) => {
    if (!project.children) return undefined;
    for (const group of project.children) {
        if (!group.children) continue;
        const found = group.children.find(ta => ta.ulid === ulid);
        if (found) return found;
    }
    return undefined;
  }) as Finder<ITriggerAction>,

  triggerGroup: ((project, ulid) => {
      if (!project.children) return undefined;
      for (const group of project.children) {
        if (!group.children) continue;
        for (const ta of group.children) {
            if (ta.triggerGroup?.ulid === ulid) return ta.triggerGroup;
        }
      }
      return undefined;
  }) as Finder<ITriggerGroup>,
  
  actionGroup: ((project, ulid) => {
      if (!project.children) return undefined;
      for (const group of project.children) {
        if (!group.children) continue;
        for (const ta of group.children) {
            if (ta.actionGroup?.ulid === ulid) return ta.actionGroup;
        }
      }
      return undefined;
  }) as Finder<IActionGroup>,

  trigger: ((project, ulid) => {
      if (!project.children) return undefined;
      for (const group of project.children) {
        if (!group.children) continue;
        for (const ta of group.children) {
            if (ta.triggerGroup?.children) {
                const found = ta.triggerGroup.children.find(t => t.ulid === ulid);
                if (found) return found;
            }
        }
      }
      return undefined;
  }) as Finder<ITrigger>,
  
  action: ((project, ulid) => {
    if (!project.children) return undefined;
      for (const group of project.children) {
        if (!group.children) continue;
        for (const ta of group.children) {
            if (ta.actionGroup?.children) {
                const found = ta.actionGroup.children.find(a => a.ulid === ulid);
                if (found) return found;
            }
        }
      }
      return undefined;
  }) as Finder<IAction>
};
