import { IEntityBase, IProject, projectStore } from '@droid/project-v2-interface';
import { useRouter } from 'next/router';
import { useEffect, useState } from 'react';
import { EntitySettingsPage } from './EntitySettingsPage';
import { Box, CircularProgress, Alert } from '@mui/material';
import { useTranslation } from '@fanfanlo';
import { Log } from '@fanfanlo';

const fileLog = new Log(false, 'EntitySettingsPageContainer');
fileLog.pause = false;

export type EntityFinder<T> = (project: IProject, entityUlid: string) => T | undefined;

interface EntitySettingsPageContainerProps<T extends IEntityBase & { ulid: string }> {
    finder: EntityFinder<T>;
    titleKey?: string;
    title?: string;
}

export function EntitySettingsPageContainer<T extends IEntityBase & { ulid: string }>({ 
    finder, titleKey, title
}: EntitySettingsPageContainerProps<T>) {
    const router = useRouter();
    const { t, i18n } = useTranslation('droid-project-v2-ui/ui/components/entity-settings/content');
    
    // 默认语言逻辑
    const defaultLang = i18n.language || 'zh-CN';
    const pageTitle = title || (titleKey ? t(titleKey) : 'Settings');
    
    // State
    const [project, setProject] = useState<IProject | null>(null);
    const [entity, setEntity] = useState<T | undefined>(undefined);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState<string | null>(null);

    // Initial Load
    useEffect(() => {
        if (!router.isReady) return;

        const { projectUlid, ulid } = router.query;
        fileLog.log('[useEffect] query:', router.query);
        
        if (!projectUlid || !ulid) {
            if (router.isReady && (!projectUlid || !ulid)) {
                 setError(t('EntitySettingsPageContainer.error.missingParams'));
                 setLoading(false);
            }
            return;
        }

        try {
            const foundProject = projectStore.findProject(projectUlid as string);
            if (!foundProject) {
                setError(t('EntitySettingsPageContainer.error.projectNotFound'));
                setLoading(false);
                return;
            }

            const foundEntity = finder(foundProject, ulid as string);
            if (!foundEntity) {
                setError(t('EntitySettingsPageContainer.error.entityNotFound'));
                setLoading(false);
                return;
            }

            setProject(foundProject);
            setEntity(foundEntity);
            setLoading(false);
        } catch (err: any) {
            setError(err.message);
            setLoading(false);
        }
    }, [router.isReady, router.query, finder, t]);

    if (loading) {
         return (
            <Box sx={{ display: 'flex', justifyContent: 'center', alignItems: 'center', height: '100vh' }}>
                <CircularProgress />
            </Box>
        );
    }
    
    if (error) {
        return (
            <Box sx={{ p: 4, display: 'flex', justifyContent: 'center' }}>
                <Alert severity="error" data-testid="EntitySettingsPageContainer__errorAlert__01JK2W6DZA5L1M8C">{error}</Alert>
            </Box>
        );
    }

    if (!project || !entity) return null;

    return (
        <EntitySettingsPage
            title={pageTitle}
            entity={entity}
        />
    );
}
